use serde_json::{Value, json};
use t3_client::thread_views::{
    composer::{code_pairs::CodePairs, input_rules::type_text},
    document::Selection,
};
fn canonical(value: &mut Value) {
    if let Some(fields) = value.as_object_mut() {
        for child in fields.values_mut() {
            canonical(child);
        }
        for field in ["attrs", "marks", "content"] {
            if fields.get(field).is_some_and(|v| {
                v.as_array().is_some_and(|v| v.is_empty())
                    || v.as_object().is_some_and(|v| v.is_empty())
            }) {
                fields.remove(field);
            }
        }
    } else if let Some(values) = value.as_array_mut() {
        for child in values.iter_mut() {
            canonical(child);
        }
        let mut merged: Vec<Value> = vec![];
        for child in values.iter() {
            if child["type"] == "text"
                && merged.last().is_some_and(|last| {
                    last["type"] == "text" && last.get("marks") == child.get("marks")
                })
            {
                if let Some(last) = merged.last_mut() {
                    last["text"] = json!(format!(
                        "{}{}",
                        last["text"].as_str().expect("text"),
                        child["text"].as_str().expect("text")
                    ));
                }
            } else {
                merged.push(child.clone());
            }
        }
        *values = merged;
    }
}
#[test]
fn original_live_input_rules_and_code_pair_precedence_match() {
    let cases: Vec<Value> = serde_json::from_str(CASES).expect("cases");
    let mut failures = vec![];
    for (index, case) in cases.into_iter().enumerate() {
        let mut doc = json!({"type":"doc","content":[{"type":case["block"]}]});
        if case["block"] == "codeBlock" {
            doc["content"][0]["attrs"] = json!({"language":"","fence":"```","close":"\n```"});
        }
        let mut marks = match case["mark"].as_str() {
            Some(mark @ ("bold" | "code")) => vec![json!({ "type": mark })],
            _ => vec![],
        };
        if case["mark"] == "markdownSource" {
            continue;
        }
        let mut selection = Selection::caret(1);
        let mut pairs = CodePairs::default();
        for ch in case["text"].as_str().expect("text").chars() {
            let rewrite = type_text(&mut pairs, &doc, selection, &ch.to_string(), &marks, false)
                .expect("insert");
            doc = rewrite.document;
            selection = rewrite.selection;
            marks = rewrite.stored_marks;
        }
        let mut expected = case["tree"].clone();
        canonical(&mut doc);
        canonical(&mut expected);
        if doc != expected || selection.head != case["caret"].as_u64().expect("caret") as usize {
            failures.push(format!(
                "{index} {} {} {}\nactual {doc}\nexpected {expected}\ncaret {} expected {}",
                case["text"], case["block"], case["mark"], selection.head, case["caret"]
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} failures\n{}",
        failures.len(),
        failures.into_iter().take(12).collect::<Vec<_>>().join("\n")
    );
}
